        );
        __AccessControl_init();
        __Pausable_init();
        __UUPSUpgradeable_init();

        factory = _factory;
        underlyingDecimals = _underlyingDecimals;

        _grantRole(DEFAULT_ADMIN_ROLE, _ownerFactory());
        _grantRole(OWNER_ROLE, _ownerFactory());
        _grantRole(UPGRADER_ROLE, _ownerFactory());
