        if (newUtilization >= _maxUtilization()) {
            revert MaxUtilizationReached(borrowToken, newUtilization, _maxUtilization());
        }

        protocolFee = (_amount * _protocolFee(borrowToken)) / 1e18;
        creatorFee = (_amount * _creatorFee()) / 1e18;
        userAmount = _amount - (protocolFee + creatorFee);

        // Mirror the withdrawal solvency check: borrowing is limited by available cash, which includes
        // accrued reserves sitting in the pool (see withdrawLiquidity). The maxUtilization cap above is
        // the primary borrow constraint; this stays a solvency backstop.
