pragma solidity ^0.8.30;

// =============================================================
//                           STRUCTS
// =============================================================

/// @notice Parameters for repaying debt with a selected token
struct RepayParams {
    address user; // User address
    address token; // Token to use for repayment
    uint256 shares; // Shares to repay
    uint256 amountOutMinimum; // Minimum output amount (slippage protection)
    bool fromPosition; // Whether to use tokens from position or wallet
    uint24 fee; // DEX fee tier (e.g., 1000 = 0.1%)
}

/// @notice Parameters for borrowing debt
/// @dev The cross-chain leg is reworked from LayerZero (OFT) to Chainlink CCIP (see Phase 7.1) and
///      stays guarded-off for the MVP. The CCIP router and destination chain selector live on the
///      pool; the CCIP fee is quoted at send time via {IRouterClient-getFee}, so no messaging-fee
///      field is carried here.
struct BorrowParams {
    uint256 amount; // Amount to borrow
    uint256 chainId; // Destination chain ID (same as source chain = local borrow)
    uint128 destGasLimit; // Destination execution gas limit for the CCIP message
}

/**
 * ______  ___  ______  _______   _______
 * | ___ \/ _ \ | ___ \|  _  \ \ / /  _  |
 * | |_/ / /_\ \| |_/ /| | | |\ V /| | | |
 * |  __/|  _  || ___ \| | | |/   \| | | |
 * | |   | | | || |_/ /\ \_/ / /^\ \ \_/ /
 * \_|   \_| |_/\____/  \___/\/   \/\___/
 */
abstract contract LendingPoolHook {
    // =============================================================
    //                           ERRORS
    // =============================================================

    /// @notice Thrown when user has insufficient collateral for an operation
    /// @param amount Requested amount
    /// @param expectedAmount Required amount
    error InsufficientCollateral(uint256 amount, uint256 expectedAmount);

    /// @notice Thrown when zero amount is provided
    error ZeroAmount();

    /// @notice Thrown when caller is not authorized
    /// @param executor Address of unauthorized caller
    error NotAuthorized(address executor);

    /// @notice Thrown when token transfer fails
    /// @param amount Amount that failed to transfer
    error TransferFailed(uint256 amount);

    /// @notice Thrown when liquidity supply amount doesn't match expected
    /// @param amount Provided amount
    /// @param expectedAmount Expected amount
    error SupplyLiquidityWrongInputAmount(uint256 amount, uint256 expectedAmount);

    /// @notice Thrown when collateral amount doesn't match expected
    /// @param amount Provided amount
    /// @param expectedAmount Expected amount
    error CollateralWrongInputAmount(uint256 amount, uint256 expectedAmount);

    /// @notice Thrown when position already exists for user
    /// @param positionAddress Existing position address
    error PositionAlreadyCreated(address positionAddress);

    /// @notice Thrown when input amount is wrong
    /// @param expectedAmount Expected amount
    /// @param actualAmount Actual amount provided
    error WrongInputAmount(uint256 expectedAmount, uint256 actualAmount);

    /// @notice Thrown when fee is only native allowed
    error FeeOnlyNativeAllowed();

    /// @notice Thrown when unexpected native token is sent
    error UnexpectedNativeToken();

    /// @notice Thrown when fallback is not allowed
    error FallbackNotAllowed();

    /// @notice Thrown when a cross-chain borrow is requested before the Chainlink CCIP leg is enabled
    /// @dev The single-chain HashKey MVP keeps cross-chain guarded-off; cross-chain reverts this until the
    ///      factory's CCIP router and the destination chainId→selector mapping are configured
    error CrossChainDisabled();

    /// @notice Thrown when the native gas supplied is below the quoted Chainlink CCIP fee
    /// @param required Fee quoted by the CCIP router
    /// @param provided Native gas supplied by the caller (msg.value)
    error InsufficientFee(uint256 required, uint256 provided);

    /// @notice Thrown when a delegate's credit-delegation allowance is below the requested borrow amount
    error InsufficientBorrowDelegation();

    /// @notice Thrown when the caller is not an authorized withdraw delegate of the beneficiary
    error WithdrawNotDelegated();

    /// @notice Thrown when the caller is not the owner, a protocol operator, or an authorized rebalance delegate
    error RebalanceNotDelegated();

    // =============================================================
    //                           EVENTS
    // =============================================================

    /// @notice Emitted when user supplies liquidity
    /// @param user User address
    /// @param amount Amount supplied
    /// @param shares Shares received
    event SupplyLiquidity(address user, uint256 amount, uint256 shares);

    /// @notice Emitted when user withdraws liquidity
    /// @param user User address
    /// @param amount Amount withdrawn
    /// @param shares Shares burned
    event WithdrawLiquidity(address user, uint256 amount, uint256 shares);

    /// @notice Emitted when user supplies collateral
    /// @param positionAddress Position contract address
    /// @param user User address
    /// @param amount Amount of collateral supplied
    event SupplyCollateral(address positionAddress, address user, uint256 amount);

    /// @notice Emitted when user repays debt
    /// @param user User address
    /// @param amount Amount repaid
    /// @param shares Shares burned
    event RepayByPosition(address user, uint256 amount, uint256 shares);

    /// @notice Emitted when new position is created
    /// @param user User address
    /// @param positionAddress Position contract address
    event CreatePosition(address user, address positionAddress);

    /// @notice Emitted when user borrows assets
    /// @param user User address
    /// @param protocolFee Protocol fee taken
    /// @param userAmount Amount user receives
    /// @param shares Borrow shares received
    /// @param amount Amount borrowed (total)
    event BorrowDebt(address user, uint256 protocolFee, uint256 userAmount, uint256 shares, uint256 amount);

    /// @notice Emitted when user borrows assets cross-chain
    /// @param user User address
    /// @param protocolFee Protocol fee taken
    /// @param userAmount Amount user receives cross-chain
    /// @param shares Borrow shares received
    /// @param params Borrow parameters
    event BorrowDebtCrossChain(address user, uint256 protocolFee, uint256 userAmount, uint256 shares, BorrowParams params);

    /// @notice Emitted when user withdraws collateral
    /// @param user User address
    /// @param amount Amount withdrawn
    event WithdrawCollateral(address user, uint256 amount);

    /// @notice Emitted when a position is liquidated
    /// @param borrower Borrower address
    /// @param borrowToken Borrow token address
    /// @param collateralToken Collateral token address
    /// @param userBorrowAssets User's borrow assets
    /// @param liquidationBonus Liquidation bonus allocation
    event Liquidation(address borrower, address borrowToken, address collateralToken, uint256 userBorrowAssets, uint256 liquidationBonus);

    /// @notice Emitted when an owner grants or updates a delegate's borrow (credit) allowance
    /// @param owner Collateral owner granting the allowance (the debt stays booked to them)
    /// @param delegate Address permitted to draw against the owner's collateral
    /// @param amount New delegated borrow allowance (0 revokes)
    event BorrowDelegationApproved(address indexed owner, address indexed delegate, uint256 amount);

    /// @notice Emitted when an owner authorizes or revokes a withdraw delegate
    /// @param owner Owner whose collateral/liquidity may be withdrawn (funds still go to the owner)
    /// @param delegate Address permitted to trigger the owner's withdrawals
    /// @param allowed Whether the delegation is enabled
    event WithdrawDelegationApproved(address indexed owner, address indexed delegate, bool allowed);

    /// @notice Emitted when an owner authorizes or revokes a rebalance delegate (e.g. an AI keeper)
    /// @param owner Owner whose position collateral may be rotated
    /// @param delegate Address permitted to rebalance the owner's position
    /// @param allowed Whether the delegation is enabled
    event RebalanceDelegationApproved(address indexed owner, address indexed delegate, bool allowed);

    /// @notice Emitted when a position's collateral is rotated via {rebalancePosition}
    /// @param user Owner of the rebalanced position
    /// @param tokenIn Collateral token sold
    /// @param tokenOut Collateral token bought
    /// @param amountIn Amount of tokenIn sold
    /// @param amountOut Amount of tokenOut received into the position
    event PositionRebalanced(address indexed user, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);

    // =============================================================
    //                           CONSTANTS
    // =============================================================

    /// @notice Role identifier for accounts that have owner privileges
    bytes32 public constant OWNER_ROLE = keccak256("OWNER_ROLE");

    /// @notice Role identifier for accounts that can upgrade the contract
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");
}

