     * @notice Opt in (or out) an address to rebalance the caller's collateral via {rebalancePosition}
     *         (e.g. authorize an AI keeper to rotate volatile collateral into a stable one before a drop).
     *         The delegate can only swap inside the caller's position; health is re-checked, funds never leave.
     * @param delegate Address permitted to rebalance the caller's position.
     * @param allowed Whether the delegation is enabled.
     * @custom:emits RebalanceDelegationApproved.
     */
    function approveRebalanceDelegation(address delegate, bool allowed) external {
        rebalanceDelegation[_msgSender()][delegate] = allowed;
        emit RebalanceDelegationApproved(_msgSender(), delegate, allowed);
    }

    // =============================================================
    //                    INTERNAL HELPER FUNCTIONS
    // =============================================================

    /**
     * @notice Shared liquidity-withdraw path: redeems `_owner`'s shares and returns the underlying to `_owner`.
     * @param _shares Shares to redeem.
     * @param _owner Owner whose shares are redeemed and who receives the underlying tokens.
     */
    function _doWithdrawLiquidity(uint256 _shares, address _owner) internal {
        uint256 amount = _withdrawLiquidity(_shares, _owner);
        _withdrawLiquidityTransfer(amount, _owner);
        emit WithdrawLiquidity(_owner, amount, _shares);
    }

    /**
     * @notice Shared collateral-withdraw path: returns `_owner`'s collateral to `_owner` and re-checks health.
     * @param _amount Amount of collateral to withdraw.
     * @param _owner Owner whose collateral is withdrawn and who receives it.
     */
    function _doWithdrawCollateral(uint256 _amount, address _owner) internal {
        _accrueInterest();
        _withdrawCollateralTransfer(_amount, _owner);
        emit WithdrawCollateral(_owner, _amount);
    }

    /**
     * @notice Creates a new Position contract for the caller if one does not already exist.
     * @dev Each user can have only one Position contract. The Position contract manages collateral and borrowed assets for the user.
     * @param _user The address of the user to create a position.
     * @custom:throws PositionAlreadyCreated if the caller already has a Position contract.
     * @custom:emits CreatePosition when a new Position is created.
     */
    function _createPosition(address _user) internal {
        address position = _addressPositions(_user);
        if (position != address(0)) revert PositionAlreadyCreated(position);
        ILPRouter(router).createPosition(_user);
        IPaboxoEmitter(_paboxoEmitter()).positionCreated(address(this), router, _user, position);
    }

    /**
     * @notice Internal function to calculate and apply accrued interest to the protocol.
     * @dev Uses dynamic interest rate model based on utilization. Updates total supply and borrow assets and last accrued timestamp.
     */
    function _accrueInterest() internal {
        ILPRouter(router).accrueInterest();
    }

    // =============================================================
    //                      ROUTER DELEGATIONS
    // =============================================================

    /**
     * @notice Gets the borrow token address from router
     * @return Address of the borrow token
     */
    function _borrowToken() internal view returns (address) {
        return ILPRouter(router).borrowToken();
    }

    /**
     * @notice Gets the collateral token address from router
     * @return Address of the collateral token
     */
    function _collateralToken() internal view returns (address) {
        return ILPRouter(router).collateralToken();
    }

    /**
     * @notice Gets user's position contract address from router
     * @param _user User address
     * @return Address of user's position contract
     */
    function _addressPositions(address _user) internal view returns (address) {
        return ILPRouter(router).addressPositions(_user);
    }

    /**
     * @notice Internal function to supply liquidity via router
     * @param _amount Amount to supply
     * @param _user User address
     * @return Shares minted
     */
    function _supplyLiquidity(uint256 _amount, address _user) internal returns (uint256) {
        return ILPRouter(router).supplyLiquidity(_amount, _user);
    }

    /**
     * @notice Internal function to withdraw liquidity via router
     * @param _shares Shares to burn
     * @param _owner Owner whose shares are redeemed
     * @return Amount withdrawn
     */
    function _withdrawLiquidity(uint256 _shares, address _owner) internal returns (uint256) {
        return ILPRouter(router).withdrawLiquidity(_shares, _owner);
    }

    /**
     * @notice Internal function to process borrow request via router
     * @param _amount Amount to borrow
     * @param _user User address
     * @return protocolFee Protocol fee amount
     * @return userAmount Amount user receives
     * @return shares Borrow shares minted
     */
    function _borrowDebt(uint256 _amount, address _user) internal returns (uint256, uint256, uint256, uint256) {
        return ILPRouter(router).borrowDebt(_amount, _user);
    }

    /**
     * @notice Gets factory contract address from router
     * @return Factory address
     */
    function _factory() internal view returns (address) {
        return ILPRouter(router).factory();
    }

    // =============================================================
    //                   FACTORY & PROTOCOL GETTERS
    // =============================================================

    /**
     * @notice Gets protocol address from factory
     * @return Protocol address
     */
    function _protocol() internal view returns (address) {
        return IFactory(_factory()).protocol();
    }

    /**
     * @notice Gets wrapped native token address from factory
     * @return Wrapped native token address
     */
    function _wrappedNative() internal view returns (address) {
        return IFactory(_factory()).wrappedNative();
    }

    /**
     * @notice Gets the owner address from factory
     * @dev Internal view function that queries the factory for the owner address
     * @return The address of the owner
     */
    function _ownerFactory() internal view returns (address) {
        return IFactory(_factory()).owner();
    }

    /**
     * @notice Gets the PaboxoEmitter address from factory
     * @return PaboxoEmitter address
     */
    function _paboxoEmitter() internal view returns (address) {
        return IFactory(_factory()).paboxoEmitter();
    }

    // =============================================================
    //                      TRANSFER HANDLERS
    // =============================================================

    /**
     * @notice Internal function to handle liquidity supply token transfer
     * @param _amount Amount to transfer
     * @dev Handles both native and ERC20 tokens
     */
    function _supplyLiquidityTransfer(uint256 _amount) internal {
        address borrowToken = _borrowToken();
        if (borrowToken == address(1)) {
            if (msg.value != _amount) revert SupplyLiquidityWrongInputAmount(msg.value, _amount);
            IWrappedNative(_wrappedNative()).deposit{ value: _amount }();
        } else {
            IERC20(borrowToken).safeTransferFrom(_msgSender(), address(this), _amount);
        }
    }

    /**
     * @notice Internal function to handle liquidity withdrawal token transfer
     * @param amount Amount to withdraw
     * @param _owner Recipient of the underlying tokens (the share owner)
     * @dev Handles both native and ERC20 tokens, unwraps native tokens
     */
    function _withdrawLiquidityTransfer(uint256 amount, address _owner) internal {
        address borrowToken = _borrowToken();
        if (borrowToken == address(1)) {
            _withdrawing = true;
            IWrappedNative(_wrappedNative()).withdraw(amount);
            (bool sent,) = _owner.call{ value: amount }("");
            if (!sent) revert TransferFailed(amount);
            _withdrawing = false;
        } else {
            IERC20(borrowToken).safeTransfer(_owner, amount);
        }
    }

    /**
     * @notice Internal function to handle collateral supply token transfer
     * @param _user User address
     * @param _amount Amount to supply
     * @dev Transfers tokens from user to their position contract
     */
    function _supplyCollateralTransfer(address _user, uint256 _amount) internal {
        address position = _addressPositions(_user);
        address collateralToken = _collateralToken();
        if (collateralToken == address(1)) {
            if (msg.value != _amount) revert CollateralWrongInputAmount(msg.value, _amount);
            address wrappedNative = _wrappedNative();
            IWrappedNative(wrappedNative).deposit{ value: msg.value }();
            // No approve needed: safeTransfer moves this pool's own wrapped-native balance. A standing
            // allowance to the Position would be a residual confused-deputy foothold, so it is omitted.
            IERC20(wrappedNative).safeTransfer(position, _amount);
        } else {
            // On-behalf: pull from the paying caller, deposit into the beneficiary's Position.
            IERC20(collateralToken).safeTransferFrom(_msgSender(), position, _amount);
        }
    }

    /**
     * @notice Internal function to handle collateral withdrawal token transfer
     * @param _amount Amount to withdraw
     * @param _owner Owner whose position is debited and who receives the collateral
     * @dev Withdraws tokens from the owner's position contract to the owner
     */
    function _withdrawCollateralTransfer(uint256 _amount, address _owner) internal {
        address position = _addressPositions(_owner);
        address tokenToCheck = _collateralToken() == address(1) ? _wrappedNative() : _collateralToken();
        uint256 userCollateralBalance = IERC20(tokenToCheck).balanceOf(position);
        if (_amount > userCollateralBalance) revert InsufficientCollateral(_amount, userCollateralBalance);
        IPosition(position).withdrawCollateral(_amount, _owner);
    }

    /**
     * @notice Internal function to handle cross-chain borrow via Chainlink CCIP
     * @dev Replaces the prior deployment's LayerZero OFT `send`. The destination is addressed by a CCIP
     *      chain selector resolved from `params.chainId` through the factory, transported over the
     *      factory's configured CCIP router. Guarded-off for the single-chain HashKey MVP: until both the
     *      CCIP router and the destination selector are set this reverts CrossChainDisabled, so the MVP
     *      never reaches a live bridge. Native-token pools bridge the wrapped-native (WHSK) representation;
     *      the protocol and creator fees stay on the source chain. The CCIP fee is quoted via
     *      {IRouterClient-getFee} and paid from native gas (msg.value): the call reverts InsufficientFee
     *      when the caller under-funds the quote, and any native gas above the quote is refunded.
     * @param _userAmount Borrowed amount bridged to the borrower on the destination chain
     * @param _creatorFee Creator fee retained on the source chain
     * @param _protocolFee Protocol fee retained on the source chain
     * @param params Borrow parameters (chainId resolves the CCIP selector, destGasLimit the callback gas)
     * @custom:throws CrossChainDisabled if the CCIP router or destination selector is unset
     * @custom:throws InsufficientFee if msg.value is below the quoted CCIP fee
     */
    function _borrowDebtCrosschain(uint256 _userAmount, uint256 _creatorFee, uint256 _protocolFee, BorrowParams memory params) internal {
        address ccipRouter = IFactory(_factory()).ccipRouter();
        uint64 destSelector = IFactory(_factory()).chainIdToSelector(params.chainId);
        if (ccipRouter == address(0) || destSelector == 0) revert CrossChainDisabled();

        // Native pools bridge the wrapped-native (WHSK) token; ERC-20 pools bridge the token itself.
        address token = _borrowToken() == address(1) ? _wrappedNative() : _borrowToken();

        // Protocol and creator fees stay on the source chain.
        IERC20(token).safeTransfer(_protocol(), _protocolFee);
        IERC20(token).safeTransfer(creator, _creatorFee);

        Client.EVMTokenAmount[] memory tokenAmounts = new Client.EVMTokenAmount[](1);
        tokenAmounts[0] = Client.EVMTokenAmount({ token: token, amount: _userAmount });

        Client.EVM2AnyMessage memory message = Client.EVM2AnyMessage({
            receiver: abi.encode(_msgSender()),
            data: "",
            tokenAmounts: tokenAmounts,
            feeToken: address(0), // pay the CCIP fee in native gas via msg.value
            extraArgs: Client._argsToBytes(Client.EVMExtraArgsV2({ gasLimit: uint256(params.destGasLimit), allowOutOfOrderExecution: true }))
        });

        IERC20(token).approve(ccipRouter, _userAmount);

        uint256 fee = IRouterClient(ccipRouter).getFee(destSelector, message);
        if (msg.value < fee) revert InsufficientFee(fee, msg.value);
        IRouterClient(ccipRouter).ccipSend{ value: fee }(destSelector, message);

        // Refund any native gas the caller over-sent beyond the quoted CCIP fee.
        uint256 refund = msg.value - fee;
        if (refund > 0) {
            (bool refunded,) = _msgSender().call{ value: refund }("");
            if (!refunded) revert TransferFailed(refund);
