     */
    function _repayWithSelectedTokenTransfer(RepayParams memory params, uint256 borrowAmount) internal {
        address borrowToken = _borrowToken();
        address userPosition = _addressPositions(params.user);

        if (params.fromPosition) {
            // Spends the borrower's OWN position collateral -> only the borrower or a registered operator may trigger it.
            _accessControl(params.user);
            SwapParams memory swapParams = SwapParams({
                tokenIn: params.token, tokenOut: borrowToken, amountIn: borrowAmount, amountOutMinimum: params.amountOutMinimum, fee: params.fee
            });
            IPosition(userPosition).repayWithSelectedToken(swapParams);
        } else {
            // On-behalf & permissionless: the caller funds the repayment (directly or via a swap from their wallet),
            // reducing params.user's debt. Only reduces the borrower's liability, so no authorization is required.
            if (params.token != borrowToken) {
                // Calculate how much of the selected token is needed for the borrowAmount
                uint256 tokenAmount = IPosition(userPosition)._tokenCalculator(borrowToken, params.token, borrowAmount);
                // Over-provision for the DEX swap cost (fee + slippage) so the swapped output still covers the
                // full debt. `_tokenCalculator` is spot (no fee) and is shared with quotes/valuation, so the
                // buffer is applied HERE, not inside it. Without it, a real fee-charging DEX (DODO ~0.3%)
                // returns < borrowAmount and trips the minOut floor below. Surplus goes to the pool (never
                // shorted). Same rationale as Position.repayWithSelectedToken (the from-position path).
                tokenAmount = (tokenAmount * WAD) / (WAD - SWAP_COST_BUFFER);
                // Floor the swap output at borrowAmount: the debt is reduced by borrowAmount, so the pool must
                // receive at least that much borrow token — this blocks the "clear debt for dust" / sandwich drain.
                uint256 minOut = params.amountOutMinimum > borrowAmount ? params.amountOutMinimum : borrowAmount;
                SwapParams memory swapParams =
                    SwapParams({ tokenIn: params.token, tokenOut: borrowToken, amountIn: tokenAmount, amountOutMinimum: minOut, fee: params.fee });
                _isNativeTransferFrom(_msgSender(), params.token, tokenAmount);
                IERC20(params.token).approve(userPosition, tokenAmount);
                IPosition(userPosition).swapTokenToBorrow(swapParams);
            } else {
                // Transfer borrow token directly from the paying caller
                _isNativeTransferFrom(_msgSender(), borrowToken, borrowAmount);
            }
        }
    }

    // =============================================================
    //                       REPAY LOGIC
    // =============================================================

    /**
     * @notice Internal function to process repayment with selected token via router
     * @param _shares Shares to repay
     * @param _user User address
     * @return borrowAmount Borrow amount repaid
     */
    function _repayWithSelectedToken(uint256 _shares, address _user) internal returns (uint256) {
        return ILPRouter(router).repayWithSelectedToken(_shares, _user);
    }

    /**
     * @notice Internal function to handle native token transfer from user
     * @param _user User address
     * @param _token Token address (address(1) for native)
     * @param _amount Amount to transfer
     * @dev Wraps native tokens or transfers ERC20
     */
    function _isNativeTransferFrom(address _user, address _token, uint256 _amount) internal {
        if (_token == address(1)) {
            if (msg.value != _amount) revert WrongInputAmount(msg.value, _amount);
            IWrappedNative(_wrappedNative()).deposit{ value: msg.value }();
        } else {
            IERC20(_token).safeTransferFrom(_user, address(this), _amount);
        }
    }

    // =============================================================
    //                    ACCESS CONTROL HELPERS
    // =============================================================

    /**
     * @notice Internal function for access control validation
     * @param _user User address to validate
     * @dev Allows operators or the user themselves
     */
    function _accessControl(address _user) internal view {
        if (_msgSender() == _user) return;
        if (!IFactory(_factory()).operator(_msgSender())) {
            revert NotAuthorized(_msgSender());
        }
    }

    /// @dev Restricts a withdrawal to `_onBehalf` themselves or an address they authorized as a withdraw
    ///      delegate via {approveWithdrawDelegation}. Reverts otherwise. Withdrawn funds always go to `_onBehalf`.
    function _authorizeOnBehalf(address _onBehalf) internal view {
        if (_msgSender() != _onBehalf && !withdrawDelegation[_onBehalf][_msgSender()]) revert WithdrawNotDelegated();
    }

    /**
     * @notice Internal function to ensure user has a position
     * @param _user User address
     * @dev Creates position if it doesn't exist
     */
    function _positionRequired(address _user) internal {
        if (_addressPositions(_user) == address(0)) {
            _createPosition(_user);
        }
    }

    /**
     * @notice Internal function to ensure non-zero amount
     * @param _amount Amount to validate
     * @dev Reverts if amount is zero
     */
    function _nonZeroAmount(uint256 _amount) internal pure {
        if (_amount == 0) revert ZeroAmount();
    }

    // =============================================================
    //                    RECEIVE & FALLBACK
    // =============================================================

    /**
     * @notice Receive function to handle incoming native tokens
     * @dev Auto-wraps native tokens when appropriate, rejects during withdrawals
     */
    receive() external payable {
        // Only auto-wrap if this is the native token lending pool and not during withdrawal
        if (msg.value > 0 && !_withdrawing && (_borrowToken() == address(1) || _collateralToken() == address(1))) {
            IWrappedNative(_wrappedNative()).deposit{ value: msg.value }();
        } else if (msg.value > 0 && _withdrawing) {
            // During withdrawal, don't wrap - just pass through
            return;
        } else if (msg.value > 0) {
            // Unexpected native token - revert to prevent loss
            revert UnexpectedNativeToken();
        }
    }

    /**
     * @notice Fallback function to prevent accidental native token loss
     * @dev Always reverts to protect users
     */
    fallback() external payable {
        // Fallback should not accept native tokens to prevent accidental loss
        revert FallbackNotAllowed();
    }

    // =============================================================
    //                       UPGRADE FUNCTIONS
    // =============================================================

    /// @notice Authorizes contract upgrades
    /// @dev Only accounts with UPGRADER_ROLE can authorize upgrades.
    ///      This is required by the UUPSUpgradeable pattern.
    /// @param newImplementation The address of the new implementation contract
    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) { }
}

